4	/**
5	 * test-script.test.ts — every directory `bun run test` names is a directory.
6	 *
7	 * ## What this is here for
8	 *
9	 * `bun test <path that does not exist>` does not fail. It runs the paths it
10	 * finds, reports them, and exits 0. So a `test` script naming a directory that
11	 * has moved runs a smaller suite than it says it does, and the only visible
12	 * symptom is a number nobody is comparing against anything.
13	 *
14	 * That happened. The tool servers moved from `.github/atoma/tools/scripts/` to
15	 * `.github/atoma-runtime/tools/`, the `test` script kept the old path, and
16	 * `mcp.test.ts` and `shell_guard.test.ts` stopped running -- in CI, which is the
17	 * only place they CAN run, because they spawn subprocesses that need a POSIX
18	 * shell. Every release since went out with the tool servers and the shell guard
19	 * untested, and CI was green for all of them. The later rename moved the stale
20	 * path to a new stale path without noticing it was stale.
21	 *
22	 * Checking the count would not have caught it either: nobody knows what the
23	 * number should be. Checking that the paths EXIST is the assertion that has an
24	 * answer.
25	 */
26	describe("the test script", () => {
27	  const script = (JSON.parse(readFileSync("package.json", "utf8")) as { scripts: Record<string, string> }).scripts;
28	
29	  /** The arguments to `bun test`, which are paths. The command itself is not. */
30	  function pathsOf(command: string): string[] {
31	    return command
32	      .split(/\s+/)
33	      .slice(2)
34	      .filter((word) => word.startsWith("./") || word.startsWith("src/") || word.startsWith("tests/"));
35	  }
36	
37	  for (const name of ["test", "test:e2e"]) {
38	    test(`\`${name}\` names only paths that exist`, () => {
39	      const command = script[name];
40	      expect(command, `package.json has no \`${name}\` script`).toBeDefined();
41	      const paths = pathsOf(command!);
42	      expect(paths.length, `\`${name}\` names no paths at all`).toBeGreaterThan(0);
43	      const missing = paths.filter((path) => !existsSync(path));
44	      expect(
45	        missing,
46	        `\`bun test\` exits 0 on a path that does not exist, so these run nothing and say nothing. ` +
47	          `Point them at where the files moved to`,
48	      ).toEqual([]);
49	    });
50	  }
